package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/**
 * Validated clerk limits for grades, with two decimals, by grade; a grade's value null: blank, none (the sheet's).
 * A grade left out is left as it is. {@code from} is the from-date typed for each grade (a grade left out: none typed,
 * the sheet's today).
 */
public record GradeClerkLimit(Map<String, BigDecimal> values, Map<String, LocalDate> from) {

    /** The from-date typed for the grade (null: none, the sheet's today). */
    public LocalDate fromOf(String grade) {
        return from.get(grade);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveGradeClerkLimit {
    public void save(@Val GradeClerkLimit limit, @Val Sheet sheet, SettingRepository repository) {
        limit.values().forEach((grade, value) -> repository.saveDated(sheet.id(), DatedSettings.gradeClerkLimit(grade),
                DatedSettings.fromOr(limit.fromOf(grade), sheet.today()), value == null ? null : value.toPlainString()));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records each grade's clerk limit just saved, by grade (blank: none), even when it is the one the grade had. */
public class AuditGradeClerkLimit {
